require __DIR__.'/bootstrap.php';
if(!installed()){header('Location: install.php');exit;}
$pdo=db();$page=trim((string)($_GET['page']??'home'));
$statuses=['open','in_progress','need_clarification','done','approved','reopened'];

function page_row(int $id):?array{$s=db()->prepare('SELECT pg.*,p.name project_name,p.base_url,p.owner_id,p.share_token,p.share_password_hash,p.id project_id FROM pages pg JOIN projects p ON p.id=pg.project_id WHERE pg.id=? LIMIT 1');$s->execute([$id]);return $s->fetch()?:null;}
function latest_capture(int $pageId):?array{$s=db()->prepare('SELECT * FROM captures WHERE page_id=? ORDER BY id DESC LIMIT 1');$s->execute([$pageId]);return $s->fetch()?:null;}
function capture_annotations(int $captureId):array{$s=db()->prepare('SELECT a.*,u.name creator_name,(SELECT COUNT(*) FROM comments c WHERE c.annotation_id=a.id) comment_count FROM annotations a LEFT JOIN users u ON u.id=a.created_by WHERE a.capture_id=? ORDER BY a.number');$s->execute([$captureId]);return $s->fetchAll();}
function shared_project(string $token):?array{$s=db()->prepare('SELECT * FROM projects WHERE share_token=? AND status="active" LIMIT 1');$s->execute([$token]);return $s->fetch()?:null;}
function share_unlocked(array $p):bool{if(empty($p['share_password_hash']))return true;return !empty($_SESSION['share_unlock'][(int)$p['id']]);}
function annotation_context(int $id):?array{$s=db()->prepare('SELECT a.*,c.page_id,pg.project_id,pg.title page_title,pg.url page_url,p.name project_name,p.owner_id,p.share_token,p.share_password_hash,c.file_path capture_path,u.name creator_name FROM annotations a JOIN captures c ON c.id=a.capture_id JOIN pages pg ON pg.id=c.page_id JOIN projects p ON p.id=pg.project_id LEFT JOIN users u ON u.id=a.created_by WHERE a.id=? LIMIT 1');$s->execute([$id]);return $s->fetch()?:null;}

