  $s=$pdo->prepare('INSERT INTO users(name,email,password) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$_SESSION['user_id']=(int)$pdo->lastInsertId();session_regenerate_id(true);go(['page'=>'projects']);
 }
 if($action==='login'){
  $email=strtolower(post('email'));$password=(string)($_POST['password']??'');$s=$pdo->prepare('SELECT * FROM users WHERE email=? LIMIT 1');$s->execute([$email]);$u=$s->fetch();
