  $s=$pdo->prepare('INSERT INTO projects(owner_id,name,base_url,share_token) VALUES(?,?,?,?)');$s->execute([$u['id'],$name,$url,random_token()]);$id=(int)$pdo->lastInsertId();$home=$url.'/';$s=$pdo->prepare('INSERT IGNORE INTO pages(project_id,title,url) VALUES(?,?,?)');$s->execute([$id,'Home',$home]);log_activity($id,(int)$u['id'],'created project','project',$id,['url'=>$url]);go(['page'=>'project','id'=>$id]);
 }
 if($action==='update-project'){
  $u=require_auth();$id=(int)post('project_id');$p=require_project($id);if(project_role($p,$u)!=='owner'){http_response_code(403);exit('Only the project owner can edit project settings.');}$name=post('name');$base=rtrim(post('base_url'),'/');if($name===''||!valid_public_url($base)){flash('error','Enter a valid project name and public URL.');go(['page'=>'project-settings','id'=>$id]);}$hash=$p['share_password_hash'];$sharePass=(string)($_POST['share_password']??'');if($sharePass!=='')$hash=password_hash($sharePass,PASSWORD_DEFAULT);if(isset($_POST['clear_share_password']))$hash=null;$s=$pdo->prepare('UPDATE projects SET name=?,base_url=?,share_password_hash=? WHERE id=?');$s->execute([$name,$base,$hash,$id]);flash('success','Project settings saved.');go(['page'=>'project-settings','id'=>$id]);
 }
 if($action==='regenerate-share'){
  $u=require_auth();$id=(int)post('project_id');$p=require_project($id);if(project_role($p,$u)!=='owner')exit('Forbidden');$token=random_token();$s=$pdo->prepare('UPDATE projects SET share_token=? WHERE id=?');$s->execute([$token,$id]);log_activity($id,(int)$u['id'],'regenerated share link','project',$id);flash('success','Share link regenerated. Old link no longer works.');go(['page'=>'project-settings','id'=>$id]);
 }
 if($action==='scan-project'){
  $u=require_auth();$id=(int)post('project_id');$p=require_project($id);if(!can_edit_project($p,$u))exit('Forbidden');$urls=discover_pages($p['base_url']);$s=$pdo->prepare('INSERT IGNORE INTO pages(project_id,title,url) VALUES(?,?,?)');$added=0;foreach($urls as $url){$path=parse_url($url,PHP_URL_PATH)?:'/';$title=$path==='/'?'Home':trim(str_replace(['-','_','/'],' ',basename(rtrim($path,'/'))));$title=$title!==''?ucwords($title):'Page';$s->execute([$id,mb_substr($title,0,190),$url]);$added+=$s->rowCount();}log_activity($id,(int)$u['id'],'scanned website','project',$id,['discovered'=>count($urls),'added'=>$added]);flash('success',"Scan finished. {$added} new page(s) added.");go(['page'=>'project','id'=>$id]);
 }
 if($action==='add-page'){
  $u=require_auth();$id=(int)post('project_id');$p=require_project($id);if(!can_edit_project($p,$u))exit('Forbidden');$url=post('url');$title=post('title');if(!valid_public_url($url)||!same_host($url,$p['base_url'])){flash('error','The page must be a public URL on this project website.');go(['page'=>'project','id'=>$id]);}$title=$title!==''?$title:(parse_url($url,PHP_URL_PATH)==='/'?'Home':'Page');$s=$pdo->prepare('INSERT IGNORE INTO pages(project_id,title,url) VALUES(?,?,?)');$s->execute([$id,mb_substr($title,0,190),$url]);flash($s->rowCount()?'success':'error',$s->rowCount()?'Page added.':'That page is already in this project.');go(['page'=>'project','id'=>$id]);
 }
 if($action==='capture-page'){
  $u=require_auth();$pageId=(int)post('page_id');$pg=page_row($pageId);if(!$pg){exit('Page not found');}$p=require_project((int)$pg['project_id']);if(!can_edit_project($p,$u))exit('Forbidden');$result=capture_pagespeed($pg['url']);if(!$result['ok']){flash('error',$result['error']);go(['page'=>'page','id'=>$pageId]);}$s=$pdo->prepare('INSERT INTO captures(page_id,file_path,width,height,source,created_by) VALUES(?,?,?,?,?,?)');$s->execute([$pageId,$result['path'],$result['width'],$result['height'],$result['source'],$u['id']]);$captureId=(int)$pdo->lastInsertId();log_activity((int)$p['id'],(int)$u['id'],'captured page','capture',$captureId,['page'=>$pg['url']]);flash('success','Fresh screenshot captured.');go(['page'=>'page','id'=>$pageId]);
