 if($action==='create-annotation'){
  $u=require_auth();$captureId=(int)post('capture_id');$s=$pdo->prepare('SELECT c.*,pg.project_id,pg.id page_id FROM captures c JOIN pages pg ON pg.id=c.page_id WHERE c.id=?');$s->execute([$captureId]);$cap=$s->fetch();if(!$cap)exit('Capture not found');$p=require_project((int)$cap['project_id']);if(!can_edit_project($p,$u))exit('Forbidden');$title=post('title');if($title===''){flash('error','Add a short change-request title.');go(['page'=>'page','id'=>$cap['page_id']]);}$next=$pdo->prepare('SELECT COALESCE(MAX(number),0)+1 FROM annotations WHERE capture_id=?');$next->execute([$captureId]);$num=(int)$next->fetchColumn();$vals=[];foreach(['x_pct','y_pct','w_pct','h_pct'] as $k){$v=(float)post($k,'0');$vals[$k]=max(0,min(100,$v));}$s=$pdo->prepare('INSERT INTO annotations(capture_id,created_by,number,x_pct,y_pct,w_pct,h_pct,title,description,requested_text,target_url) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$captureId,$u['id'],$num,$vals['x_pct'],$vals['y_pct'],$vals['w_pct'],$vals['h_pct'],$title,post('description'),post('requested_text'),post('target_url')]);$annId=(int)$pdo->lastInsertId();try{$att=save_attachment('attachment',$annId);if($att){$a=$pdo->prepare('INSERT INTO attachments(annotation_id,original_name,file_path,mime_type,file_size) VALUES(?,?,?,?,?)');$a->execute([$att['annotation_id'],$att['original_name'],$att['file_path'],$att['mime_type'],$att['file_size']]);}}catch(Throwable $ex){flash('error',$ex->getMessage());}log_activity((int)$p['id'],(int)$u['id'],'created change request','annotation',$annId,['number'=>$num,'title'=>$title]);flash('success','Change request #'.$num.' created.');go(['page'=>'issue','id'=>$annId]);
 }
 if($action==='update-status'){
  $u=require_auth();$id=(int)post('annotation_id');$ctx=annotation_context($id);if(!$ctx)exit('Issue not found');$p=require_project((int)$ctx['project_id']);if(!can_edit_project($p,$u))exit('Forbidden');$status=post('status');if(!in_array($status,$statuses,true))exit('Invalid status');$s=$pdo->prepare('UPDATE annotations SET status=? WHERE id=?');$s->execute([$status,$id]);log_activity((int)$p['id'],(int)$u['id'],'changed status','annotation',$id,['status'=>$status]);flash('success','Status updated.');go(['page'=>'issue','id'=>$id]);
 }
 if($action==='comment'){
  $id=(int)post('annotation_id');$ctx=annotation_context($id);if(!$ctx)exit('Issue not found');$shareToken=post('share_token');$u=user();$isShare=$shareToken!==''&&hash_equals($ctx['share_token'],$shareToken);if($isShare){$p=shared_project($shareToken);if(!$p||!share_unlocked($p))exit('Share access required');$uid=null;$guest=mb_substr(post('guest_name','Reviewer'),0,120);}else{$p=require_project((int)$ctx['project_id']);$uid=(int)$u['id'];$guest=null;}$body=post('body');if($body===''){flash('error','Comment cannot be empty.');$isShare?go(['page'=>'share-issue','token'=>$shareToken,'id'=>$id]):go(['page'=>'issue','id'=>$id]);}$s=$pdo->prepare('INSERT INTO comments(annotation_id,user_id,guest_name,body,parent_id) VALUES(?,?,?,?,?)');$parent=(int)post('parent_id','0');$s->execute([$id,$uid,$guest,$body,$parent?:null]);log_activity((int)$ctx['project_id'],$uid,'commented','annotation',$id);$isShare?go(['page'=>'share-issue','token'=>$shareToken,'id'=>$id]):go(['page'=>'issue','id'=>$id]);
 }
